package com.bank.priv;

import java.util.logging.*;

public class PrivateEc2Demo {
    private static final Logger log = Logger.getLogger("PrivateEC2");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        PrivateInstance settlement = new PrivateInstance("i-0settlement", false); // no public IP

        AccessPathResolver access = new AccessPathResolver();
        log.info(() -> "Preferred access path: " + access.resolve(settlement, true, true));

        RouteTable rt = new RouteTable();
        rt.addRoute("10.0.0.0/16", "local");
        rt.addRoute("0.0.0.0/0", "nat-0gateway123");   // outbound only via NAT

        log.info(() -> "Reach internal 10.0.5.9 via: " + rt.pathTo("10.0.5.9"));
        log.info(() -> "Outbound to 52.1.2.3 (patch server) via: " + rt.pathTo("52.1.2.3"));
        log.warning(() -> "Inbound from internet directly allowed: " + settlement.hasPublicIp());
    }
}

// ─── Would be in PrivateInstance.java ───
class PrivateInstance {
    private final String id; private final boolean publicIp;
    PrivateInstance(String id, boolean publicIp) { this.id = id; this.publicIp = publicIp; }
    boolean hasPublicIp() { return publicIp; }
    String id() { return id; }
}

// ─── Would be in RouteTable.java ───
class RouteTable {
    private final java.util.LinkedHashMap<String, String> routes = new java.util.LinkedHashMap<>();
    void addRoute(String cidr, String target) { routes.put(cidr, target); }
    String pathTo(String ip) {
        // Most specific match first; local for VPC, NAT for the default route.
        if (ip.startsWith("10.")) return routes.get("10.0.0.0/16");
        return routes.getOrDefault("0.0.0.0/0", "no route — unreachable") + " (outbound only)";
    }
}

// ─── Would be in AccessPathResolver.java ───
class AccessPathResolver {
    String resolve(PrivateInstance inst, boolean ssmEnabled, boolean hasRole) {
        if (inst.hasPublicIp()) return "direct SSH (but private instance should NOT have public IP)";
        if (ssmEnabled && hasRole) return "SSM Session Manager (no inbound ports, audited)";
        return "bastion/jump host in public subnet, then internal SSH";
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
